-- Prepared for Phase B. Not applied to production in the visual MVP.
PRAGMA foreign_keys=ON;
CREATE TABLE users(id TEXT PRIMARY KEY,auth_subject TEXT NOT NULL UNIQUE,email TEXT NOT NULL,full_name TEXT,role TEXT NOT NULL DEFAULT 'customer' CHECK(role IN ('customer','admin')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE products(id TEXT PRIMARY KEY,slug TEXT NOT NULL UNIQUE,title TEXT NOT NULL,short_description TEXT,description TEXT,price_cents INTEGER NOT NULL CHECK(price_cents>=0),sale_price_cents INTEGER CHECK(sale_price_cents>=0 AND sale_price_cents<=price_cents),status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','active','archived')),featured INTEGER NOT NULL DEFAULT 0 CHECK(featured IN (0,1)),is_kit INTEGER NOT NULL DEFAULT 0 CHECK(is_kit IN (0,1)),license_text TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE taxonomies(id TEXT PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN ('occasion','celebration','theme','type')),slug TEXT NOT NULL,label TEXT NOT NULL,parent_id TEXT REFERENCES taxonomies(id),sort_order INTEGER NOT NULL DEFAULT 0,UNIQUE(kind,slug));
CREATE TABLE product_taxonomies(product_id TEXT NOT NULL REFERENCES products(id),taxonomy_id TEXT NOT NULL REFERENCES taxonomies(id),PRIMARY KEY(product_id,taxonomy_id));
CREATE INDEX taxonomy_products ON product_taxonomies(taxonomy_id,product_id);
CREATE TABLE product_media(id TEXT PRIMARY KEY,product_id TEXT NOT NULL REFERENCES products(id),object_key TEXT NOT NULL,alt_text TEXT NOT NULL,sort_order INTEGER NOT NULL DEFAULT 0,is_cover INTEGER NOT NULL DEFAULT 0);
CREATE TABLE product_files(id TEXT PRIMARY KEY,product_id TEXT NOT NULL REFERENCES products(id),object_key TEXT NOT NULL UNIQUE,original_filename TEXT NOT NULL,mime_type TEXT NOT NULL,bytes INTEGER NOT NULL CHECK(bytes>0),sha256 TEXT NOT NULL,format TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,is_active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE coupons(id TEXT PRIMARY KEY,code TEXT NOT NULL COLLATE NOCASE UNIQUE,discount_type TEXT NOT NULL CHECK(discount_type IN ('percent','fixed')),value INTEGER NOT NULL CHECK(value>0),starts_at TEXT,ends_at TEXT,max_uses INTEGER CHECK(max_uses>0),use_count INTEGER NOT NULL DEFAULT 0 CHECK(use_count>=0),active INTEGER NOT NULL DEFAULT 1,CHECK(discount_type!='percent' OR value<=100),CHECK(ends_at IS NULL OR starts_at IS NULL OR ends_at>starts_at));
CREATE TABLE orders(id TEXT PRIMARY KEY,order_number TEXT NOT NULL UNIQUE,user_id TEXT NOT NULL REFERENCES users(id),currency TEXT NOT NULL DEFAULT 'BRL' CHECK(currency='BRL'),subtotal_cents INTEGER NOT NULL CHECK(subtotal_cents>=0),discount_cents INTEGER NOT NULL DEFAULT 0 CHECK(discount_cents>=0),total_cents INTEGER NOT NULL CHECK(total_cents>=0),coupon_id TEXT REFERENCES coupons(id),status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','paid','failed','cancelled','refunded')),payment_provider TEXT,provider_reference TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,paid_at TEXT,CHECK(total_cents=subtotal_cents-discount_cents));
CREATE INDEX orders_user_created ON orders(user_id,created_at);
CREATE TABLE order_items(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),product_id TEXT NOT NULL REFERENCES products(id),product_title_snapshot TEXT NOT NULL,unit_price_cents INTEGER NOT NULL CHECK(unit_price_cents>=0),quantity INTEGER NOT NULL DEFAULT 1 CHECK(quantity=1),UNIQUE(order_id,product_id));
CREATE TABLE payments(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),provider TEXT NOT NULL,provider_payment_id TEXT NOT NULL,provider_status TEXT NOT NULL,amount_cents INTEGER NOT NULL CHECK(amount_cents>=0),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(provider,provider_payment_id));
CREATE TABLE webhook_events(id TEXT PRIMARY KEY,provider TEXT NOT NULL,event_id TEXT NOT NULL,payload_digest TEXT NOT NULL,processed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(provider,event_id));
CREATE TABLE download_events(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),order_item_id TEXT NOT NULL REFERENCES order_items(id),product_file_id TEXT NOT NULL REFERENCES product_files(id),downloaded_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX downloads_user ON download_events(user_id,downloaded_at);
CREATE TABLE site_settings(key TEXT PRIMARY KEY,value_json TEXT NOT NULL CHECK(json_valid(value_json)),updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE banners(id TEXT PRIMARY KEY,image_key TEXT,title TEXT NOT NULL,description TEXT,cta_label TEXT,cta_href TEXT,active INTEGER NOT NULL DEFAULT 1,sort_order INTEGER NOT NULL DEFAULT 0);
